const crypto = require('crypto');

const item = $input.first().json;
const body = item.body && typeof item.body === 'object' ? item.body : item;
const m = body.metrics && typeof body.metrics === 'object' ? body.metrics : {};

const status = String(m.plant_status || m.status || 'unknown').toLowerCase();
const signingInput = JSON.stringify({ metrics: m, plant_status: status });
const secret = String($env.HOLOBRAIN_HMAC_SECRET || '').trim();
const hdrRaw = item.headers || {};
const headerSig = hdrRaw['x-holobrain-hmac'] || hdrRaw['X-Holobrain-HMAC'];

if (secret && headerSig) {
  const expected = crypto.createHmac('sha256', secret).update(signingInput, 'utf8').digest('hex');
  let ok = false;
  if (typeof headerSig === 'string' && headerSig.length === expected.length && /^[0-9a-f]+$/i.test(headerSig)) {
    try {
      ok = crypto.timingSafeEqual(Buffer.from(headerSig, 'hex'), Buffer.from(expected, 'hex'));
    } catch (e) {
      ok = false;
    }
  }
  if (!ok) {
    return [{
      json: {
        error: 'invalid_hmac',
        code: 'HOLO_HMAC_001',
        timestamp: new Date().toISOString(),
      },
    }];
  }
}

const colors = { optimal: '228B22', warning: 'FFD700', critical: 'DC143C', unknown: '808080' };
const color = colors[status] || colors.unknown;

let hmac_signature = '';
if (secret) {
  hmac_signature = crypto.createHmac('sha256', secret).update(signingInput, 'utf8').digest('hex');
}

const hologramData = {
  visualization: {
    type: '3d_plant',
    status,
    color,
    hmac_signature,
  },
  metrics: {
    ph: m.ph != null ? Number(m.ph) : null,
    ec: m.ec != null ? Number(m.ec) : null,
    temperature: m.temperature != null ? Number(m.temperature) : null,
    sensor_id: m.sensor_id != null ? String(m.sensor_id) : null,
  },
  narration_hint: status === 'critical'
    ? 'Alerta crítica. Revisar actuadores y protocolo de contención antes de acción automática.'
    : 'Estado dentro de banda operativa documentada.',
};

return [{ json: hologramData }];
